window.CHAMONIX_DATA_PARTS=window.CHAMONIX_DATA_PARTS||[];window.CHAMONIX_DATA_PARTS[20]="\",\"credit\":\"你提供的旅行实景截图 · 室外水疗池水中躺椅\",\"source\":\"\",\"local\":true,\"note\":\"游客拍摄图片，请勿将人物照片视为官方宣传物料\"},\"ski1_alt\":{\"url\":\"data:image/webp;base64,\",\"credit\":\"La Vormaine · 雪区远山与宽阔雪地（你提供的第 2 张）\",\"source\":\"用户提供的照片\",\"local\":true,\"note\":\"本次网站更新使用的实景图片\"},\"nh_geneva_room\":{\"url\":\"data:image/webp;base64,\",\"credit\":\"NH Geneva Airport Hotel · 客房（取自你提供的预订网站截图）\",\"source\":\"用户提供的照片\",\"local\":true,\"note\":\"本次网站更新使用的实景图片\"}},\"hotels\":[{\"id\":\"aiglons\",\"label\":\"综合最推荐\",\"name\":\"Hôtel Les Aiglons Chamonix\",\"short\":\"Les Aiglons\",\"images\":[\"aiglons_0\",\"aiglons_1\",\"aiglons_2\",\"aiglons_3\",\"aiglons_4\"],\"tagline\":\"雪山室外恒温泳池 · 交通便利\",\"description\":\"现代度假氛围，优点是全年加热的室外泳池、室外按摩池与 SPA 休息设施；紧邻 Chamonix Sud 汽车站，机场接驳和滑雪巴士都方便。现有泳池照片部分为夏季实拍，冬季开放状态及当日景观仍需以酒店公告为准。\",\"features\":[\"室外加热泳池\",\"户外热水按摩池\",\"桑拿 + 蒸汽浴\",\"Casa Nonna 餐厅\",\"靠近汽车站\"],\"pros\":[\"室外泳池能看山景，接驳方便\",\"室外泡水欣赏勃朗峰\",\"机场接驳更轻松\"],\"cons\":[\"没有大型室内泳池\",\"具体山景取决于房型\"],\"spa\":\"室外泳池 / Jacuzzi / 桑拿 / Hammam\",\"view\":\"优先选择泳池或勃朗峰方向房型\",\"transport\":\"靠近 Chamonix Sud 汽车站\",\"url\":\"https://aiglons.com/en\",\"map\":\"Hôtel Les Aiglons Chamonix, 270 Avenue de Courmayeur, Chamonix, France\"},{\"id\":\"prieure\",\"label\":\"房间氛围最佳\",\"name\":\"Chalet Hôtel Le Prieuré & Spa\",\"short\":\"Le Prieuré\",\"images\":[\"prieure_0\",\"prieure_1\",\"prieure_2\",\"prieure_3\",\"prieure_4\"],\"tagline\":\"山景阳台 · 法式木屋 · 传统风格\",\"description\":\"传统阿尔卑斯木屋风格，山景客房、室内水疗和木质装饰都很有度假氛围。你提供的实拍里包括外观、房间、露台、桑拿及室内泳池；部分带阳台房型风景更好，SPA 使用时段建议订房前核实。\",\"features\":[\"阳台山景房\",\"小型室内水池\",\"Jacuzzi + 室外桑拿\",\"传统萨瓦餐厅\",\"靠近南针峰缆车\"],\"pros\":[\"木屋氛围与部分房型的山景阳台\",\"靠近南针峰缆车与镇中心\",\"适合偏安静、重视房间体验的旅客\"],\"cons\":[\"没有室外泳池\",\"SPA 官方“2小时”条款需确认次数\"],\"spa\":\"室内小水池 / Jacuzzi / 室外桑拿 / Hammam\",\"view\":\"确认预订是否为 Mont-Blanc 山景阳台房\",\"transport\":\"南针峰缆车站步行约 6 分钟\",\"url\":\"https://en.prieurechamonix.com/\",\"map\":\"Chalet Hôtel Le Prieuré & Spa, 149 Allée Recteur Payot, Chamonix, France\"},{\"id\":\"lykke\",\"label\":\"水疗设施最全\",\"name\":\"Lykke Hôtel & Spa Chamonix\",\"short\":\"Lykke\",\"images\":[\"lykke_0\",\"lykke_1\",\"lykke_2\",\"lykke_3\",\"lykke_4\"],\"tagline\":\"15m 室内泳池 · 室内外 Jacuzzi\",\"description\":\"现代设计风格，室内水疗设施相对齐全，包含室内泳池、Jacuzzi、桑拿和蒸汽浴。临近火车站，去 Montenvers 红色登山小火车方便。你给的照片同时包含室内泳池、冬季阳台景观和雪中室外热水池。\",\"features\":[\"15m 室内泳池\",\"室内 + 室外 Jacuzzi\",\"桑拿 + 蒸汽浴\",\"健身房、餐厅\",\"靠近 Montenvers 车站\"],\"pros\":[\"室内大泳池和水疗设备全面\",\"靠近火车站与 Montenvers 出发点\",\"滑雪后回酒店放松方便\"],\"cons\":[\"没有室外大泳池\"],\"spa\":\"550㎡ Spa / 15m泳池 / 两个 Jacuzzi / 桑拿\",\"view\":\"山景及阳台随房型变化\",\"transport\":\"靠近霞慕尼 SNCF 火车站\",\"url\":\"https://en.lykkechamonix.com/\",\"map\":\"Lykke Hotel Spa Chamonix, 39 Rue des Allobroges, Chamonix, France\"}],\"days\":[{\"d\":\"06\",\"wd\":\"周六\",\"title\":\"抵达霞慕尼 · 南针峰\",\"sub\":\"把第一天用起来，但保留天气退路\",\"category\":\"雪山观景\",\"photos\":[\"midi\",\"midipeak\",\"midi_cable\",\"midi_portrait\"],\"schedule\":[[\"07:05\",\"CA861 抵达日内瓦机场\"],[\"08:30–11:30\",\"入境、取行李、预约接驳至霞慕尼（预估）\"],[\"11:30–12:30\",\"酒店寄存行李、简单午餐\"],[\"12:30–16:00\",\"南针峰缆车 / 3,842m 观景平台 / 玻璃箱\"],[\"16:30 后\",\"入住酒店，霞慕尼晚餐\"]],\"travel\":\"从霞慕尼镇内步行约 10–20 分钟到南针峰缆车站；高峰期和天气可能延误。\",\"warning\":\"当天南针峰末次往返登山预计 15:00。抵达航班延误或天气不好，就与 7 日行程互换；不要将未能上山视为失误。\",\"url\":\"https://aiguilledumidi.montblancnaturalresort.com/fr/horaires-tarifs\",\"map\":\"Téléphérique de l’Aiguille du Midi, 100 Place de l’Aiguille du Midi, Chamonix, France\"},{\"d\":\"07\",\"wd\":\"周日\",\"title\":\"红色小火车 · 蓝冰洞 · 过山车\",\"sub\":\"三个项目彼此顺路，全天留给冰川\",\"category\":\"冰川与乐园\",\"photos\":[\"train\",\"cave\",\"coaster\",\"train_alt\",\"cave_alt\",\"cave_third\",\"train_third\"],\"schedule\":[[\"09:30–10:00\",\"早餐后步行至 Montenvers 火车站\"],[\"10:00–13:30\",\"红色小火车 / 山上观景 / 缆车及楼梯进蓝冰洞\"],[\"13:30–14:30\",\"午餐、乘小火车返回镇上\"],[\"15:00–16:00\",\"Les Planards 轨道过山车 Luge sur Rails\"],[\"16:00 后\",\"咖啡馆、小镇漫步、自由活动\"]],\"travel\":\"Montenvers 火车站距镇中心步行约 5–15 分钟，返回山下后走约 5–10 分钟到 Les Planards 轨道过山车。\",\"warning\":\"蓝冰洞需缆车 + 约 170–200 级台阶；雪季小火车往返游览建议留 3–4 小时。2 月冬季最后能参观冰洞的山下火车常为 14:30，出行前复核。\",\"url\":\"https://www.montenverstrain.com/horaires-et-tarifs-du-train-du-montenvers-mer-de-glace/\",\"map\":\"Train du Montenvers, 35 Place de la Mer de Glace, Chamonix, France\"},{\"d\":\"08\",\"wd\":\"周一\",\"title\":\"滑雪 Day 1 · La Vormaine\",\"sub\":\"宽绿道找感觉，蓝道按状态选择\",\"category\":\"滑雪\",\"photos\":[\"ski1\",\"ski1_alt\"],\"schedule\":[[\"09:30\",\"早餐、取雪具、出发乘巴士\"],[\"10:30–12:30\",\"La Vormaine 绿道热身与转弯练习\"],[\"12:30–13:30\",\"雪场午餐与休息\"],[\"13:30–16:00\",\"绿道 / 森林蓝道，按体力练习\"],[\"17:00 后\",\"回酒店休息、晚餐\"]],\"travel\":\"霞慕尼出发乘当地巴士至 Le Tour，下车步行至 La Vormaine；当天确认滑雪巴士路线与班次。\",\"warning\":\"La Vormaine 有 3 条绿道、1 条蓝道，较适合目前主要滑蓝道、犁式转弯的水平。雪票与雪具租赁分开计价。\",\"url\":\"https://en.chamonix.com/things-to-see-and-do/sports-and-outdoor/skiing-in-chamonix-mont-blanc-valley/list-of-ski-areas/domaine-skiable-la-vormaine\",\"map\":\"La Vormaine Ski Area, Le Tour, Chamonix, France\"},{\"d\":\"09\",\"wd\":\"周二\",\"title\":\"滑雪 Day 2 · Les Houches\",\"sub\":\"第二天体验不同的森林雪道\",\"category\":\"滑雪\",\"photos\":[\"ski2\",\"ski2_alt\"],\"schedule\":[[\"09:30\",\"早餐、准备雪具\"],[\"10:30–12:30\",\"前往 Prarion 缆车，选简单绿/蓝道\"],[\"12:30–13:30\",\"雪场午餐\"],[\"13:30–16:00\",\"根据状态继续滑雪；必要时乘缆车下山\"],[\"17:00 后\",\"返回霞慕尼\"]],\"travel\":\"从霞慕尼乘巴士往 Les Houches / Prarion。不是从 La Vormaine 直接滑过去，两个雪区相互独立。\",\"warning\":\"Les Houches 有容易的练习区，也有较难的红黑道；不要因为想滑回山脚而误入 Kandahar 等高难线路。若第一天还不熟练，可继续去 La Vormaine。\",\"url\":\"https://en.chamonix.com/debuter-le-ski-dans-la-vallee-de-chamonix\",\"map\":\"Télécabine du Prarion, Les Houches, France\"},{\"d\":\"10\",\"wd\":\"周三\",\"title\":\"狗拉雪橇 · QC Spa 雪山水疗\",\"sub\":\"一动一静，最有特色的放松日\",\"category\":\"特色体验\",\"photos\":[\"dog\",\"qc\",\"qc_alt\",\"qc_third\"],\"schedule\":[[\"09:30–10:30\",\"酒店早餐\"],[\"约 10:30–13:30\",\"根据最终集合地点前往狗拉雪橇场地并体验\"],[\"13:30–15:30\",\"午餐、回酒店休息\"],[\"16:00–19:30\",\"QC Spa 室内外雪山水疗\"],[\"20:00\",\"晚餐\"]],\"travel\":\"QC Spa 位于霞慕尼镇北侧，镇中心步行或当地巴士可达。狗拉雪橇地点目前仅确认运营商有 Les Molliets 场地；不能按镇内步行计算。\",\"warning\":\"重点待确认：Huskydalen 2 月 10 日具体集合地点、场次、两位成人能否同乘及交通。QC Spa 并非已确认天然矿物温泉。\",\"url\":\"https://www.huskydalen.com/activites\",\"map\":\"QC Spa Chamonix, 480 Promenade du Fori, Chamonix, France\"},{\"d\":\"11\",\"wd\":\"周四\",\"title\":\"霞慕尼小镇 · 返回日内瓦入住机场酒店\",\"sub\":\"入住 NH 日内瓦机场酒店 · 2 月 11 日至 12 日\",\"category\":\"城市休闲\",\"photos\":[\"nh_geneva_room\",\"town\"],\"schedule\":[[\"09:30–10:30\",\"早餐、退房或寄存行李\"],[\"10:30–12:30\",\"步行街、纪念品、咖啡馆\"],[\"12:30–14:00\",\"午餐、取行李\"],[\"约 14:30\",\"乘预约接驳车前往日内瓦\"],[\"傍晚\",\"入住 NH Geneva Airport Hotel（NH 日内瓦机场酒店），1 晚；为 12 日航班预留机场交通时间\"]],\"travel\":\"从霞慕尼乘预约接驳返回日内瓦。入住 NH Geneva Airport Hotel（NH 日内瓦机场酒店）；酒店位于 Avenue de Mategnin 21, 1217 Meyrin, Switzerland。建议提前确认接驳车是否能送达酒店，以及 12 日前往机场的交通。\",\"warning\":\"11 日入住、12 日退房，共 1 晚。房型及可用接送服务请以实际预订/酒店通知为准。12 日 CA862 12:20 起飞时刻需以机票为准。\",\"url\":\"https://en.chamonix.com/\",\"map\":\"NH Geneva Airport Hotel, Avenue de Mategnin 21, 1217 Meyrin, Switzerland\"},{\"d\":\"12\",\"wd\":\"周五\",\"title\":\"日内瓦机场 · 返回北京\",\"sub\":\"从 NH 日内瓦机场酒店退房，前往机场返京\",\"category\":\"返程\",\"photos\":[],\"schedule\":[[\"08:30–09:00\",\"在 NH Geneva Airport Hotel 早餐、退房\"],[\"09:00–10:00\",\"按航司要求提前抵达日内瓦机场\"],[\"12:20\",\"CA862 日内瓦机场起飞（以出票为准）\"],[\"2 月 13 日 05:30\",\"北京首都机场抵达（按之前查询的计划航班）\"]],\"travel\":\"NH Geneva Airport Hotel 位于 Avenue de Mategnin 21, 1217 Meyrin, Switzerland。请提前向酒店确认当天去日内瓦机场的交通，预留值机及安检时间。\",\"warning\":\"航班时刻来自原先查询的行程，尚未在此页面实时确认；请以实际出票记录为准。\",\"url\":\"https://www.gva.ch/en/\",\"map\":\"Geneva Airport, Switzerland\"}],\"attractions\":[{\"k\":\"midi\",\"title\":\"南针峰 Aiguille du Midi\",\"en\":\"3,842m / Mont Blanc panorama\",\"tag\":\"高山必玩\",\"desc\":\"两段高山缆车直达阿尔卑斯之巅；玻璃观景箱 “Step into the Void” 与 360° 雪山景色是精华。\",\"duration\":\"3–4小时\",\"images\":[\"midi\",\"midipeak\",\"midi_cable\",\"midi_portrait\"],\"url\":\"https://aiguilledumidi.montblancnaturalresort.com/fr/horaires-tarifs\",\"intro\":\"从霞慕尼镇内乘两段高山缆车，先到 Plan de l’Aiguille，再上到海拔约 3,842 米的南针峰站。它是观光平台而不是普通滑雪山顶；你可以从岩壁观景台俯瞰山谷、看勃朗峰与冰川，以及体验透明玻璃观景箱。\",\"experience\":[\"先在山下确认天气与已预约的入场时段，再乘两段缆车上山\",\"高山观景平台和玻璃箱都值得停留，云雾太厚时视野可能很差\",\"海拔高、温差大，保暖、墨镜、防滑鞋不可少\"],\"tips\":\"计划 2 月 6 日下午游玩，但这天是机场抵达日；不建议购买完全不可改签的时段。遇大风停运或云层浓厚，可以与 7 日或其他晴天调换。\",\"transit\":\"霞慕尼镇中心步行约 10–20 分钟到 100 Place de l’Aiguille du Midi。\",\"weather\":\"强依赖晴天和风力\",\"photos_note\":\"官网可核对缆车运行情况和峰顶实时摄像头\"},{\"k\":\"train\",\"title\":\"Montenvers 红色小火车\",\"en\":\"Rack railway / Glacier viewpoint\",\"tag\":\"和蓝冰洞一条线\",\"desc\":\"乘约 20 分钟经典红色齿轨列车上山，看冰海冰川、雪峰和观景平台，再衔接下行缆车去蓝冰洞。\",\"duration\":\"与冰洞合计 3–4 小时\",\"images\":[\"train\",\"train_alt\",\"train_third\"],\"url\":\"https://www.montenverstrain.com/horaires-et-tarifs-du-train-du-montenvers-mer-de-glace/\",\"intro\":\"Montenvers 是一条历史悠久的红色齿轨铁路，连接霞慕尼镇与海拔约 1,913 米的冰海冰川观景区。单程约 20 分钟，车窗外经过森林、山谷和雪峰；到山顶后还可以近距离观察 Mer de Glace 冰川与周围山脊。\",\"experience\":[\"坐在火车靠窗位置，体验红色经典车厢和蜿蜒的登山铁路\",\"到 Montenvers 后先去观景平台，看冰川谷地与 Les Drus 山峰\",\"再衔接同景区的下行缆车和蓝冰洞，不要把它当作另一趟独立旅游线路\"],\"tips\":\"2 月 7 日建议上午出发，小火车、冰洞、拍照和排队连起来预留 3–4 小时。下山后再去旁边的轨道过山车。\",\"transit\":\"镇中心步行约 5–15 分钟到 35 Place de la Mer de Glace；坐红色小火车上山。\",\"weather\":\"低能见度影响景色；班次和冰洞可能临时调整\"},{\"k\":\"cave\",\"title\":\"蓝冰洞 Grotte de Glace\",\"en\":\"Inside Mer de Glace\",\"tag\":\"冰川内部\",\"desc\":\"走进冰川内部的蓝色冰壁通道，需乘下行缆车并走约 170–200 级台阶。与红色小火车同一景区，不建议拆开。\",\"duration\":\"洞内约 20–30 分钟\",\"images\":[\"cave\",\"cave_alt\",\"cave_third\"],\"url\":\"https://www.chamonix.com/activites/informations-pratiques-remontees-mecaniques/mer-de-glace-et-train-du-montenvers\",\"intro\":\"Grotte de Glace 是人工每年重新开凿在天然冰川里的蓝色洞穴。蓝色来自冰体对光的吸收和散射，人在其中可以看到压实冰层、雕刻与冰川内部的纹理，氛围像走进“冰晶隧道”。冰洞不大，但体验很特别。\",\"experience\":[\"先坐红色小火车到 Montenvers 山上站\",\"换乘下行缆车，随后通过约 170 级台阶抵达洞口\",\"冰洞内观赏蓝色冰壁及冰雕，再按原路返回山上站和火车站\"],\"tips\":\"冬季步行台阶可能湿滑，不建议穿平底光滑鞋；冰洞空间温度低，带保暖衣物。站点不适合有明显行动困难的游客。\",\"transit\":\"不能从霞慕尼镇直接步行到冰洞，必须先走 Montenvers 红色小火车线路。\",\"weather\":\"依赖冰洞、缆车与火车三者同步开放\"},{\"k\":\"coaster\",\"title\":\"Alpine Coaster 轨道雪橇\",\"en\":\"Les Planards / Luge sur Rails\",\"tag\":\"顺路、轻松\",\"desc\":\"两人可同乘沿固定轨道滑行的橙色小车，自己控制速度。就在 Montenvers 山下火车站附近。\",\"duration\":\"预留 20–60 分钟\",\"images\":[\"coaster\"],\"url\":\"https://www.planards.fr/luge-sur-rails/\",\"intro\":\"你在小红书看到的“雪山过山车”，官方也叫 Luge sur Rails 或 Alpine Coaster，位于 Les Planards 游乐场。它是固定金属轨道上的橙色滑车，而不是坐雪圈沿雪坡下滑；两位成人可同坐一车，行驶过程可控制速度。\",\"experience\":[\"轨道约 1.3 公里，沿弯道、起伏和环形弯逐步下降\",\"沿途能看到雪地、森林与山坡，体验时间本身只有几分钟\",\"就在 Montenvers 山下火车站附近，特别适合小火车返程后顺路玩\"],\"tips\":\"不要误以为当天一定不用排队：周末和学校假期尽量留 20–60 分钟。通常可以到场购票，不必专门为它安排半天。\",\"transit\":\"从红色小火车山下车站步行约 5–10 分钟，地址 351 Chemin du Pied du Grépon。\",\"weather\":\"户外项目，运营受天气影响\"},{\"k\":\"ski1\",\"title\":\"La Vormaine 初级雪区\",\"en\":\"3 green runs + 1 blue run\",\"tag\":\"适合第一天\",\"desc\":\"宽阔绿道、森林蓝道、风景开阔；适合先恢复技术。旁边的 Balme 主雪区难度不同，不是同一张初级日票可随意覆盖。\",\"duration\":\"滑雪 1 天\",\"images\":[\"ski1\",\"ski1_alt\"],\"url\":\"https://en.chamonix.com/things-to-see-and-do/sports-and-outdoor/skiing-in-chamonix-mont-blanc-valley/list-of-ski-areas/domaine-skiable-la-vormaine\",\"intro\":\"La Vormaine 是 Le Tour 山脚的独立初级练习区：4 条拖牵式索道，3 条宽绿道和 1 条森林蓝道，旁边还有教学活动区与雪橇区。这里不是靠长雪道取胜，而是视野开阔、坡度比较温和、适合放慢节奏找回转弯节奏。\",\"experience\":[\"上午先在宽绿道熟悉雪鞋、雪板、刹车和转弯\",\"等能稳定控制速度、顺利使用拖牵索道后，再考虑森林蓝道\",\"有面向雪山的休息露台，适合中午晒太阳和吃饭\"],\"tips\":\"你目前蓝道基本能滑、但主要犁式转弯，所以第一天选择这里合理。如果发现绿道已经过于简单，可询问教练是否适合升级；不要把山脚 La Vormaine 和更大的 Balme 主雪区混作一张独立票。 这里的两张雪场照片使用你新提供的 La Vormaine 实景截图。\",\"transit\":\"从镇中心乘冬季巴士前往 Le Tour，巴士站接近雪区；单程需按当日班次预留约 25–40 分钟。\",\"weather\":\"山脚雪区相对更注重基础练习，雪况需当天确认\"},{\"k\":\"ski2\",\"title\":\"Les Houches 森林滑雪\",\"en\":\"Prarion beginner area\",\"tag\":\"第二天可选\",\"desc\":\"森林景观与阿尔卑斯山雪道；根据水平选顶部容易的区域。更陡的红黑道请避开，必要时乘缆车下山。\",\"duration\":\"滑雪 1 天\",\"images\":[\"ski2\",\"ski2_alt\"],\"url\":\"https://en.chamonix.com/debuter-le-ski-dans-la-vallee-de-chamonix\",\"intro\":\"Les Houches–Saint-Gervais 是霞慕尼山谷更完整的滑雪区，约有 55 公里雪道，最高在 Prarion 一带约 1,900 米。相比 La Vormaine 的山脚练习坡，这里能体验更长的滑行、树林之间的路线，以及勃朗峰景观，适合第二天想尝试“真正高山滑雪感”的人。\",\"experience\":[\"建议从 Prarion 缆车上山，先看山顶 Ecole 绿道与练习区域\",\"选择已经确认的简单蓝道，不要因为想滑回酒店或山脚勉强挑战陡坡\",\"部分下山路线较难，如果没有合适的简单返程雪道，直接坐缆车下山\"],\"tips\":\"著名的 Kandahar 是高难度竞赛赛道，绝不是绿道。Les Houches 的优势是场景更丰富，但不意味着所有蓝道都比 La Vormaine 容易。若前一天还觉得吃力，第二天继续在 La Vormaine 练习更合适。 这里的两张雪场照片使用你新提供的 Les Houches 实景截图。\",\"transit\":\"霞慕尼镇乘冬季巴士前往 Les Houches 的 Prarion 或 Bellevue，下车进缆车站；参考约 20–35 分钟车程，实际以当日班次为准。\",\"weather\":\"林间雪道在部分天气中更有遮挡，但上山缆车和雪道仍依赖天气\"},{\"k\":\"dog\",\"title\":\"Huskydalen 狗拉雪橇\",\"en\":\"Chiens de traîneau\",\"tag\":\"集合地点待确认\",\"desc\":\"专业雪橇驾驶员带领哈士奇犬队体验雪地穿行。官方 2026/27 季具体集合点尚未最终核实。\",\"duration\":\"体验套餐约 1 小时 + 交通\",\"images\":[\"dog\"],\"url\":\"https://www.huskydalen.com/activites\",\"intro\":\"狗拉雪橇是由雪橇驾驶员（Musher）带领雪橇犬队穿行雪地的体验。通常会有和狗狗互动、讲解装备及乘坐环节，但“套餐总时长”和“真正坐在雪橇上的时间”并不完全相同，需以运营商的具体套餐为准。\",\"experience\":[\"提前约定 2 月 10 日的场次、集合点和两人是否可同乘\",\"做好防寒：手套、保暖鞋、外套，最好戴帽子和围脖\",\"不要自行摸犬只或站在犬队前方，听从 Mush​​er 指引\"],\"tips\":\"这是行程里唯一暂时不能确认就在霞慕尼镇旁的项目。Huskydalen 公开展示过 Les Molliets / Les Carroz 场地，需明确 2 月 10 日到底在哪出发、有没有接送，才能决定是否和下午 QC Spa 放在一起。\",\"transit\":\"集合点未确认；若是 Les Molliets，则从霞慕尼需单独安排往返交通，不能按镇内步行规划。\",\"weather\":\"明显依赖雪况与运营商时间安排\"},{\"k\":\"qc\",\"title\":\"QC Spa Chamonix\",\"en\":\"Outdoor warm-water pools\",\"tag\":\"滑雪后放松\",\"desc\":\"雪山背景下的室外热水景观池、桑拿、蒸汽浴与舒适休息区。是独立 SPA，不是酒店内的天然矿物温泉。\",\"duration\":\"建议 3–4 小时\",\"images\":[\"qc\",\"qc_alt\",\"qc_third\"],\"url\":\"https://www.qcterme.com/destinations/chamonix/qc-spa-chamonix/admissions-prices-chx\",\"intro\":\"QC Spa Chamonix 是独立水疗中心，不是酒店，也不能直接认定使用天然矿物温泉水。最吸引人的体验是在雪山包围下泡室外热水池，并在室内水疗池、桑拿、蒸汽浴和休息区之间慢慢切换。\",\"experience\":[\"建议 2 月 10 日下午约 16:00 入场，先在白天看雪山，再欣赏傍晚景色\",\"可以选择室外热水池、室内水流按摩、桑拿与休息空间\",\"部分时段提供 Aperiterme 小食饮品，正式套餐内容以预订票种为准\"],\"tips\":\"安排在连续滑雪两天之后很舒服。提前核对 16:00 时段是否开放以及票内是否包含浴袍、拖鞋和饮品，按摩护理需单独确认。 本页照片是游客上传的水疗参考实拍，其中包含非冬季照片，具体现场与冬季使用规则请以运营方为准。\",\"transit\":\"位于 480 Promenade du Fori，在镇中心北侧，步行或当地巴士可到。\",\"weather\":\"无须完全晴天，但室外雪山景观在晴朗时更明显\"}]}";